<?php require __DIR__.'/../config/config.php'; if(!empty($_SESSION['admin_id'])){header('Location: index.php');exit;} $err='';if($_SERVER['REQUEST_METHOD']==='POST'){$s=db()->prepare('SELECT * FROM admins WHERE email=?');$s->execute([trim($_POST['email'])]);$a=$s->fetch();if($a&&password_verify($_POST['password'],$a['password_hash'])){session_regenerate_id(true);$_SESSION['admin_id']=$a['id'];header('Location: index.php');exit;}$err='Incorrect email or password.';} ?><!doctype html><html><head><meta charset="utf-8"><link rel="stylesheet" href="../assets/style.css"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Admin login</title></head><body><main style="max-width:450px"><h1>KigoTech Admin</h1><p><?=htmlspecialchars($err)?></p><form method="post"><div class="field">Email<input name="email" type="email" required></div><div class="field">Password<input name="password" type="password" required></div><button class="primary">Sign in</button></form></main></body></html>
